const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const date = '2017-09-24';

  // Polygon for the western basin of Lake Erie, known for being shallower and more nutrient-rich.
  const westernBasin = ee.Geometry.Polygon([[
    [-83.4, 41.5], [-82.4, 41.5], [-82.4, 42.1], [-83.4, 42.1], [-83.4, 41.5]
  ]]);

  // Polygon for the eastern basin of Lake Erie, which is deeper and generally clearer.
  const easternBasin = ee.Geometry.Polygon([[
    [-80.2, 42.2], [-79.0, 42.2], [-79.0, 42.8], [-80.2, 42.8], [-80.2, 42.2]
  ]]);

  // 2. Data Acquisition & Filtering
  const collection = ee.ImageCollection('COPERNICUS/S3/OLCI')
    .filterBounds(westernBasin.union(easternBasin))
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  // 3. Data Check and Processing
  const imageCount = collection.size().getInfo();
  if (imageCount === 0) {
    console.log(`No Sentinel-3 OLCI images found for ${date}.`);
    console.log('A: No');
    return;
  }
  console.log(`Images found on ${date}: ${imageCount}`);

  // Mosaic images for the day and select the Chlorophyll-a band.
  // The 'CHL_NN' band provides an estimate of chlorophyll concentration in mg/m^3.
  const image = collection.select('CHL_NN').mosaic();

  // The quality flag 'QF_IN' indicates land or invalid pixels. We mask them out.
  const qualityMask = collection.select('QF_IN').mosaic().neq(0);
  const maskedImage = image.updateMask(qualityMask.not());

  // 4. Calculation
  const scale = 1000; // Use a reasonable scale for regional analysis to avoid timeouts.
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const westStats = maskedImage.reduceRegion({
    reducer: reducer,
    geometry: westernBasin,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const eastStats = maskedImage.reduceRegion({
    reducer: reducer,
    geometry: easternBasin,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const westChl = westStats['CHL_NN_mean'];
  const westCount = westStats['CHL_NN_count'];
  const eastChl = eastStats['CHL_NN_mean'];
  const eastCount = eastStats['CHL_NN_count'];

  console.log(`Western Basin Valid Pixels: ${westCount}`);
  console.log(`Eastern Basin Valid Pixels: ${eastCount}`);

  // 5. Validation & Final Answer
  if (westCount === 0 || eastCount === 0) {
    console.log('No valid, cloud-free pixels in one or both basins after masking.');
    console.log('C2');
    return;
  }

  if (westChl === null || eastChl === null) {
      console.log('Calculation failed: Mean value is null for one or both basins.');
      console.log('C3');
      return;
  }

  console.log(`Western Basin Mean Chl-a (mg/m^3): ${westChl.toFixed(2)}`);
  console.log(`Eastern Basin Mean Chl-a (mg/m^3): ${eastChl.toFixed(2)}`);

  if (westChl > eastChl) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D');
});
